css:
.ycc-container {
  padding: 22px;
  background: radial-gradient(1200px 600px at 20% -10%, #14233b 0%, #0a1422 55%, #060c16 100%);
  min-height: 100vh;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  color: #c9d6e8;
}
.ycc-container h1, .ycc-container h3, .ycc-container h4 { margin: 0; }

.ycc-header {
  background: linear-gradient(135deg, #0f2a47 0%, #11375f 100%);
  border: 1px solid #1c4670;
  color: #eaf2ff;
  padding: 26px 28px;
  border-radius: 14px;
  margin-bottom: 22px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.45);
  border-left: 5px solid #38bdf8;
}
.ycc-header h1 { font-size: 1.7rem; font-weight: 700; letter-spacing: 0.3px; }
.ycc-header p { font-size: 0.95rem; opacity: 0.78; margin: 6px 0 0; font-family: 'Consolas','SFMono-Regular',monospace; }

.ycc-period-counter {
  text-align: center;
  font-size: 1.05rem;
  color: #7fa8d4;
  margin-bottom: 20px;
  font-weight: 600;
  font-family: 'Consolas','SFMono-Regular',monospace;
  text-transform: uppercase;
  letter-spacing: 0.12em;
}

.ycc-status-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 14px;
  margin-bottom: 22px;
}
.ycc-status-card {
  background: linear-gradient(160deg, #0e1d31 0%, #0b1626 100%);
  border: 1px solid #1b304d;
  border-radius: 12px;
  padding: 16px 14px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
  text-align: center;
  border-top: 3px solid #2b4a6f;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.ycc-status-card:hover { transform: translateY(-3px); box-shadow: 0 8px 20px rgba(0,0,0,0.55); }
.ycc-card-cet1 { border-top-color: #38bdf8; grid-column: span 2; background: linear-gradient(160deg, #0c2236 0%, #0a1a2c 100%); }
.ycc-card-portfolio { border-top-color: #34d399; }
.ycc-card-return { border-top-color: #a78bfa; }
.ycc-card-sharpe { border-top-color: #f0abfc; }
.ycc-card-drawdown { border-top-color: #fb7185; }
.ycc-card-duration { border-top-color: #fbbf24; }

.ycc-label {
  color: #6f8bad;
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 6px;
  font-weight: 600;
}
.ycc-value {
  font-size: 1.45rem;
  font-weight: 700;
  color: #eaf2ff;
  font-family: 'Consolas','SFMono-Regular',monospace;
}
.ycc-hero { font-size: 2.7rem; line-height: 1.05; color: #5eead4; }
.ycc-sub { font-size: 0.68rem; color: #5f7da0; margin-top: 4px; font-family: 'Consolas','SFMono-Regular',monospace; }

.ycc-cet1-ok { color: #34d399 !important; }
.ycc-cet1-warn { color: #fbbf24 !important; }
.ycc-cet1-breach { color: #fb7185 !important; }

.ycc-mandate-box {
  background: linear-gradient(135deg, #1a1530 0%, #181228 100%);
  border: 1px solid #4c3b7a;
  border-left: 5px solid #a78bfa;
  border-radius: 12px;
  padding: 18px 22px;
  margin-bottom: 20px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
}
.ycc-mandate-box h4 { color: #c4b5fd; margin-bottom: 8px; font-size: 1rem; text-transform: uppercase; letter-spacing: 0.06em; }
.ycc-mandate-box #mandateText { font-size: 0.92rem; color: #cdc2ec; line-height: 1.55; }

.ycc-briefing {
  background: linear-gradient(160deg, #0e1d31 0%, #0a1626 100%);
  border: 1px solid #1b304d;
  border-left: 5px solid #38bdf8;
  border-radius: 12px;
  padding: 22px 24px;
  margin-bottom: 20px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
}
.ycc-briefing h3 { color: #9ad0f5; margin-bottom: 12px; font-size: 1.12rem; }
.ycc-briefing #briefingText { font-size: 0.94rem; line-height: 1.6; color: #b9cae0; }

.ycc-event-box {
  background: linear-gradient(135deg, #2a1414 0%, #241010 100%);
  border: 1px solid #7f2d2d;
  border-left: 5px solid #fb7185;
  border-radius: 12px;
  padding: 18px 22px;
  margin-bottom: 20px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
}
.ycc-event-box h4 { color: #fda4af; margin-bottom: 8px; font-size: 1rem; text-transform: uppercase; letter-spacing: 0.06em; }
.ycc-event-box #eventText { font-size: 0.92rem; color: #f3cdd2; line-height: 1.55; }

.ycc-controls {
  background: linear-gradient(160deg, #0e1d31 0%, #0a1626 100%);
  border: 1px solid #1b304d;
  border-radius: 12px;
  padding: 24px;
  margin-bottom: 22px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
}
.ycc-controls h3 { color: #9ad0f5; margin-bottom: 18px; font-size: 1.12rem; }
.ycc-alloc-hint { color: #7fa8d4; font-size: 0.85rem; margin-bottom: 16px; font-family: 'Consolas','SFMono-Regular',monospace; }

.ycc-decision-group { margin-bottom: 16px; }
.ycc-decision-group label {
  display: block;
  font-weight: 600;
  color: #aac4e2;
  margin-bottom: 6px;
  font-size: 0.88rem;
}
.ycc-decision-group select,
.ycc-decision-group input {
  width: 100%;
  padding: 10px 12px;
  border: 1px solid #284a73;
  border-radius: 9px;
  font-size: 0.9rem;
  background-color: #0c1c30;
  color: #e6eefb;
  transition: border-color 0.2s, box-shadow 0.2s;
}
.ycc-decision-group select option {
  background-color: #0c1c30;
  color: #e6eefb;
}
.ycc-decision-group select:focus,
.ycc-decision-group input:focus {
  border-color: #38bdf8;
  outline: none;
  box-shadow: 0 0 0 3px rgba(56,189,248,0.18);
}
.ycc-decision-group input::placeholder { color: #5f7da0; }

.ycc-submit-btn {
  width: 100%;
  padding: 14px;
  border-radius: 10px;
  font-size: 1.02rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  background: linear-gradient(135deg, #0ea5e9 0%, #2563eb 100%);
  border: none;
  color: #fff;
  margin-top: 8px;
  transition: transform 0.2s, box-shadow 0.2s;
}
.ycc-submit-btn:hover { transform: translateY(-2px); box-shadow: 0 6px 18px rgba(37,99,235,0.45); }
.ycc-undo-btn {
  width: 100%;
  margin-top: 8px;
  border-radius: 9px;
  background: transparent;
  color: #7fa8d4;
  border: 1px solid #284a73;
}
.ycc-undo-btn:hover { background: #0c1c30; color: #bcd6f5; }

.ycc-charts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  margin-bottom: 22px;
}
.ycc-chart-wrapper {
  background: linear-gradient(160deg, #0e1d31 0%, #0a1626 100%);
  border: 1px solid #1b304d;
  border-radius: 12px;
  padding: 16px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
  height: 340px;
}

.ycc-history {
  background: linear-gradient(160deg, #0e1d31 0%, #0a1626 100%);
  border: 1px solid #1b304d;
  border-radius: 12px;
  padding: 14px 18px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.4);
  overflow-x: auto;
}
.ycc-history table { color: #c9d6e8; margin: 0; font-size: 0.86rem; }
.ycc-history table th {
  color: #7fa8d4;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  font-size: 0.72rem;
  border-top: none;
  border-bottom: 1px solid #1b304d;
}
.ycc-history table td { border-color: #14253c; font-family: 'Consolas','SFMono-Regular',monospace; }
.ycc-history .table-striped tbody tr:nth-of-type(odd) { background-color: rgba(56,189,248,0.05); }

@media (max-width: 768px) {
  .ycc-container { padding: 14px; }
  .ycc-header h1 { font-size: 1.35rem; }
  .ycc-status-cards { grid-template-columns: repeat(2, 1fr); }
  .ycc-card-cet1 { grid-column: span 2; }
  .ycc-hero { font-size: 2.1rem; }
  .ycc-charts { grid-template-columns: 1fr; }
  .ycc-chart-wrapper { height: 300px; }
}


/* FIX v1.1.0 - completion / committee-verdict screen */
.ycc-completion { padding: 8px 4px; text-align: center; }
.ycc-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #6b7280; margin-bottom: 6px; }
.ycc-completion-verdict { font-size: 24px; font-weight: 700; color: #0f172a; margin-bottom: 14px; }
.ycc-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 18px; }
.ycc-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 14px; background: #f1f5f9; border-radius: 8px; min-width: 90px; }
.ycc-completion-metric span { font-size: 11px; letter-spacing: .04em; text-transform: uppercase; color: #6b7280; }
.ycc-completion-metric strong { font-size: 18px; color: #0f172a; }
.ycc-completion-insights-heading { font-size: 12px; letter-spacing: .06em; text-transform: uppercase; color: #6b7280; margin-bottom: 8px; }
.ycc-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 640px; text-align: left; }
.ycc-completion-insights li { padding: 10px 14px; margin-bottom: 8px; background: #f8fafc; border-left: 3px solid #0f766e; border-radius: 4px; color: #1e293b; font-size: 14px; }

