(function () {
  'use strict';

  var RF = 3.0;            // risk-free / overnight rate after the shock (%)
  var PORTFOLIO = 9000;    // EUR millions
  var HIDDEN_LOSS = 180;   // EUR millions, amortized-cost hidden loss

  // Per-bucket forward expected return (%), annualized volatility (%), and the
  // mark-to-market shock already taken on the existing book (%).
  var BUCKETS = {
    equity: { ret: 7.0, vol: 18.0, shock: -8.0, dur: 0 },
    short:  { ret: 3.3, vol: 3.5,  shock: -1.5, dur: 2.0 },
    long:   { ret: 4.2, vol: 9.5,  shock: -4.0, dur: 8.0 },
    cash:   { ret: 3.0, vol: 0.4,  shock: 0.0,  dur: 0.1 }
  };

  function eur(v) {
    var bn = v / 1000;
    return '€' + bn.toFixed(2) + 'bn';
  }
  function eurM(v) { return '€' + Math.round(v) + 'M'; }
  function pct1(v) { return (Math.round(v * 10) / 10).toFixed(1) + '%'; }

  class YieldCurveAdapter extends USF.SimulationAdapter {
    constructor() {
      super();
      this.name = 'The Yield Curve Call';
      this.version = '1.1.0';
    }

    initialize(state) {
      if (!state.domainState || Object.keys(state.domainState).length === 0) {
        state.domainState = {
          cet1: 14.2,
          cet1Floor: 11.0,
          boardTrigger: 12.0,
          portfolio: PORTFOLIO,
          expReturn: 3.1,
          sharpe: 0.42,
          drawdown: 0.0,
          duration: 5.8,
          // weights (%)
          wEquity: 20, wShort: 0, wLong: 80, wCash: 0,
          // mandate (set in round 2)
          mandateSet: false,
          limitDuration: 4.5,
          limitEquity: 20,
          limitDrawdown: 6,
          limitCet1: 12.0,
          // flags
          crystallized: false,
          score: 0,
          breaches: 0,
          // history arrays for charts
          cet1History: [],
          portfolioHistory: [],
          returnHistory: [],
          drawdownHistory: [],
          equityHistory: [],
          shortHistory: [],
          longHistory: [],
          cashHistory: []
        };
      }
      if (!state.decisions || Object.keys(state.decisions).length === 0) {
        state.decisions = {
          diagDuration: 'correct', diagShape: 'flatten', diagHidden: 'flag',
          limitDuration: '4.5', limitEquity: '20', limitDrawdown: '6', limitCet1: '12.0',
          equity: 18, short: 32, long: 35, cash: 15,
          sellAmort: 'no', thesis: 'yield_capture', stance: 'hold'
        };
      }
      this._updateBriefing(state);
    }

    validateDecisions(decisions) {
      var state = window.mySimulation.state;
      var round = state.currentPeriod || 1;
      var t = function (k) { return window.mySimulation.t(k); };
      var warn = function (k) {
        window.mySimulation.uiManager.showNotification(t(k), 'warning');
      };

      if (round === 1) {
        var dd = document.getElementById('diagDurationSelect');
        var ds = document.getElementById('diagShapeSelect');
        var dh = document.getElementById('diagHiddenSelect');
        if (dd) decisions.diagDuration = dd.value;
        if (ds) decisions.diagShape = ds.value;
        if (dh) decisions.diagHidden = dh.value;
        return true;
      }

      if (round === 2) {
        var ld = document.getElementById('limitDurationSelect');
        var le = document.getElementById('limitEquitySelect');
        var lk = document.getElementById('limitDrawdownSelect');
        var lc = document.getElementById('limitCet1Select');
        if (ld) decisions.limitDuration = ld.value;
        if (le) decisions.limitEquity = le.value;
        if (lk) decisions.limitDrawdown = lk.value;
        if (lc) decisions.limitCet1 = lc.value;
        return true;
      }

      // rounds 3 and 4: allocation must sum to 100
      var prefix = round === 3 ? 'r3' : 'r4';
      var eqEl = document.getElementById(prefix + 'EquityInput');
      var shEl = document.getElementById(prefix + 'ShortInput');
      var loEl = document.getElementById(prefix + 'LongInput');
      var caEl = document.getElementById(prefix + 'CashInput');
      var eq = eqEl ? parseFloat(eqEl.value) : NaN;
      var sh = shEl ? parseFloat(shEl.value) : NaN;
      var lo = loEl ? parseFloat(loEl.value) : NaN;
      var ca = caEl ? parseFloat(caEl.value) : NaN;

      if (!Number.isFinite(eq) || !Number.isFinite(sh) || !Number.isFinite(lo) || !Number.isFinite(ca)) {
        warn('warn_numeric');
        return false;
      }
      if (eq < 0 || sh < 0 || lo < 0 || ca < 0) {
        warn('warn_negative');
        return false;
      }
      var sum = eq + sh + lo + ca;
      if (Math.abs(sum - 100) > 0.5) {
        warn('warn_sum');
        return false;
      }
      // a bank book needs liquidity to fund the deposit outflow (€1.5bn ≈ 16.7%)
      if (ca < 5) {
        warn('warn_liquidity');
        return false;
      }

      decisions.equity = eq;
      decisions.short = sh;
      decisions.long = lo;
      decisions.cash = ca;

      if (round === 3) {
        var sa = document.getElementById('r3SellAmortSelect');
        var th = document.getElementById('r3ThesisSelect');
        if (sa) decisions.sellAmort = sa.value;
        if (th) decisions.thesis = th.value;
      } else {
        var st = document.getElementById('r4StanceSelect');
        var sa4 = document.getElementById('r4SellAmortSelect');
        if (st) decisions.stance = st.value;
        if (sa4) decisions.sellAmort = sa4.value;
      }
      return true;
    }

    // Pure helper: compute portfolio metrics from weights (no I/O).
    _computePortfolio(wEquity, wShort, wLong, wCash) {
      var we = wEquity / 100, ws = wShort / 100, wl = wLong / 100, wc = wCash / 100;
      var ret = we * BUCKETS.equity.ret + ws * BUCKETS.short.ret +
                wl * BUCKETS.long.ret + wc * BUCKETS.cash.ret;
      // simple risk aggregation with a diversification haircut between equity and bonds
      var bondVol = (ws * BUCKETS.short.vol + wl * BUCKETS.long.vol) / Math.max(ws + wl, 0.0001);
      var eqVar = we * we * Math.pow(BUCKETS.equity.vol, 2);
      var bondW = ws + wl;
      var bondVar = bondW * bondW * Math.pow(bondVol, 2);
      var cross = 2 * we * bondW * 0.25 * BUCKETS.equity.vol * bondVol; // rho≈0.25
      var vol = Math.sqrt(Math.max(eqVar + bondVar + cross, 0.01));
      var sharpe = vol > 0.2 ? (ret - RF) / vol : 0;
      var dur = ws * BUCKETS.short.dur + wl * BUCKETS.long.dur + wc * BUCKETS.cash.dur;
      // worst-case 1-period drawdown ≈ a 1.65σ adverse move scaled by 0.6 horizon
      var drawdown = vol * 1.65 * 0.6;
      return {
        ret: Math.round(ret * 100) / 100,
        vol: Math.round(vol * 100) / 100,
        sharpe: Math.round(sharpe * 100) / 100,
        duration: Math.round(dur * 100) / 100,
        drawdown: Math.round(drawdown * 100) / 100
      };
    }

    calculateResults(state) {
      var d = state.decisions;
      var ds = state.domainState;
      var round = state.currentPeriod;
      var results = { period: round };
      var self = this;

      if (round === 1) {
        // Diagnosis round: no reallocation. Apply the shock to the legacy 20/80 book
        // and score how accurately the team read the exposure.
        var legacy = this._computePortfolio(20, 0, 80, 0);
        // realized mark from the shock on the legacy book
        var shockMark = 0.20 * BUCKETS.equity.shock + 0.80 * BUCKETS.long.shock; // ≈ -4.8%
        var lossEur = Math.abs(shockMark) / 100 * PORTFOLIO;
        // CET1 hit from FVOCI losses ≈ 80 bps
        var cet1Hit = 0.80;
        ds.cet1 = Math.round((ds.cet1 - cet1Hit) * 100) / 100;
        ds.portfolio = Math.round(PORTFOLIO * (1 + shockMark / 100));
        ds.expReturn = legacy.ret;
        ds.sharpe = legacy.sharpe;
        ds.duration = 5.8;
        ds.drawdown = Math.round(Math.abs(shockMark) * 100) / 100;
        ds.wEquity = 20; ds.wShort = 0; ds.wLong = 80; ds.wCash = 0;

        var diagScore = 0;
        if (d.diagDuration === 'correct') diagScore += 34;
        else if (d.diagDuration === 'under') diagScore += 8;
        else diagScore += 5; // catastrophic over-reaction
        if (d.diagShape === 'flatten') diagScore += 33;
        else diagScore += 6;
        if (d.diagHidden === 'flag') diagScore += 33;
        else diagScore += 4;
        ds.score += diagScore;
        results.roundName = 'diag';
        results.diagScore = diagScore;
        results.lossEur = Math.round(lossEur);
        results.cet1Hit = cet1Hit;
      } else if (round === 2) {
        // Governance round: lock the mandate. No reallocation; metrics unchanged.
        ds.limitDuration = parseFloat(d.limitDuration);
        ds.limitEquity = parseFloat(d.limitEquity);
        ds.limitDrawdown = parseFloat(d.limitDrawdown);
        ds.limitCet1 = parseFloat(d.limitCet1);
        ds.mandateSet = true;
        // Reward a coherent, prudent mandate; punish an incoherent or reckless one.
        var mScore = 0;
        if (ds.limitCet1 >= 12.0) mScore += 12; else mScore += 4;
        if (ds.limitDuration <= 4.5) mScore += 8; else mScore += 4;
        if (ds.limitEquity <= 20) mScore += 6; else mScore += 3;
        if (ds.limitDrawdown <= 6) mScore += 6; else mScore += 3;
        ds.score += mScore;
        results.roundName = 'mandate';
        results.mandateScore = mScore;
      } else {
        // Rounds 3 & 4: real reallocation under the shock / second leg.
        // Round 4 lands a deposit-outflow + second-leg shock surprise.
        var secondLeg = round === 4;
        var bk = JSON.parse(JSON.stringify(BUCKETS));
        if (secondLeg) {
          // second-leg: a further small long-end sell-off + equity wobble,
          // but yields are now even more attractive (higher forward returns).
          bk.long.shock = -2.0; bk.equity.shock = -3.0;
          bk.long.ret = 4.6; bk.short.ret = 3.5; bk.equity.ret = 7.5;
        }

        var m = this._computePortfolio(d.equity, d.short, d.long, d.cash);

        // Mark-to-market move from holding/rotating into the shocked buckets this round.
        var markPct = (d.equity / 100) * bk.equity.shock +
                      (d.short / 100) * bk.short.shock +
                      (d.long / 100) * bk.long.shock +
                      (d.cash / 100) * bk.cash.shock;
        // Forward return on the new book actually feeds CET1 recovery via retained earnings.
        var fwd = (d.equity / 100) * bk.equity.ret + (d.short / 100) * bk.short.ret +
                  (d.long / 100) * bk.long.ret + (d.cash / 100) * bk.cash.ret;

        // CET1 walk:
        //  - FVOCI mark moves capital roughly markPct * 0.18 (sensitivity of CET1 to portfolio MtM)
        //  - retained forward return adds a little back
        var cet1Delta = markPct * 0.18 + (fwd - RF) * 0.04;
        // Crystallizing the hidden amortized-cost loss hits capital ~30 bps.
        var crystalHit = 0;
        if (d.sellAmort === 'yes' && !ds.crystallized) {
          crystalHit = HIDDEN_LOSS / PORTFOLIO * 100 * 0.18; // ≈ 0.36 -> ~0.30bps scaled
          crystalHit = Math.round(crystalHit * 100) / 100;
          ds.crystallized = true;
        }
        // If they DON'T sell amortized cost but hold too little cash they still fund the
        // outflow from FVOCI/short — handled by the cash>=5 validation. A deeper second-leg
        // outflow in round 4 punishes very low cash.
        var outflowPenalty = 0;
        if (secondLeg && d.cash < 12) {
          outflowPenalty = (12 - d.cash) * 0.03; // forced fire-sale to meet the run
        }

        var newCet1 = ds.cet1 + cet1Delta - crystalHit - outflowPenalty;
        newCet1 = Math.round(newCet1 * 100) / 100;

        ds.cet1 = newCet1;
        ds.expReturn = m.ret;
        ds.sharpe = m.sharpe;
        ds.duration = m.duration;
        ds.drawdown = m.drawdown;
        ds.portfolio = Math.round(PORTFOLIO * (1 + markPct / 100));
        ds.wEquity = d.equity; ds.wShort = d.short; ds.wLong = d.long; ds.wCash = d.cash;

        // ---- scoring ----
        var roundScore = 0;
        var breaches = [];

        // Capital floor: hard. Breaching the 11.0% requirement is catastrophic.
        if (newCet1 < ds.cet1Floor) {
          roundScore -= 40; breaches.push('floor');
        } else if (newCet1 < ds.boardTrigger) {
          roundScore -= 12; breaches.push('trigger');
        } else {
          roundScore += 14;
        }

        // Mandate discipline: breaching your own R2 limits costs you (Common Error 3).
        if (ds.mandateSet) {
          if (d.equity > ds.limitEquity + 0.5) { roundScore -= 16; breaches.push('equity_cap'); }
          if (m.duration > ds.limitDuration + 0.25) { roundScore -= 14; breaches.push('duration_band'); }
          if (m.drawdown > ds.limitDrawdown + 0.3) { roundScore -= 12; breaches.push('drawdown_ceiling'); }
          if (newCet1 < ds.limitCet1 - 0.05) { roundScore -= 14; breaches.push('cet1_floor'); }
          if (breaches.indexOf('equity_cap') === -1 &&
              breaches.indexOf('duration_band') === -1 &&
              breaches.indexOf('drawdown_ceiling') === -1 &&
              breaches.indexOf('cet1_floor') === -1) {
            roundScore += 10; // held the line
          }
        }

        // Risk-adjusted return: reward Sharpe, but only inside the capital boundary.
        roundScore += Math.max(0, Math.round(m.sharpe * 18));

        // Earning your cost of capital. The shock handed you decade-high yields:
        // a book that earns little more than the overnight rate under-performs even if
        // it is "safe". This makes conservatism-that-never-re-risks an explicit cost.
        roundScore += Math.round((m.ret - RF) * 6);
        if (m.ret < RF + 0.4) roundScore -= 6; // parked in cash, capturing almost no yield

        // Expected-return thesis discipline (Beltratti). Reward a coherent thesis;
        // punish "no thesis" and conservatism that never re-risks.
        if (round === 3) {
          if (d.thesis === 'none') roundScore -= 8;
          else if (d.thesis === 'yield_capture' && d.long + d.short >= 55) roundScore += 8;
          else if (d.thesis === 'equity_rerate' && d.equity >= ds.limitEquity - 2) roundScore += 4;
          else if (d.thesis === 'wait_cash' && d.cash >= 28) roundScore -= 2; // hiding, not allocating
        }
        if (round === 4) {
          // Conservatism that never re-risks is its own kind of loss.
          if (d.stance === 'rebuild' && d.long >= 38) roundScore += 10;
          else if (d.stance === 'hold' && d.long >= 30) roundScore += 5;
          else if (d.stance === 'derisk' && d.cash > 25) roundScore -= 10;
        }

        ds.breaches += breaches.length;
        ds.score += roundScore;

        results.roundName = round === 3 ? 'reallocate' : 'recover';
        results.cet1 = newCet1;
        results.cet1Delta = Math.round((cet1Delta - crystalHit - outflowPenalty) * 100) / 100;
        results.expReturn = m.ret;
        results.sharpe = m.sharpe;
        results.duration = m.duration;
        results.drawdown = m.drawdown;
        results.roundScore = roundScore;
        results.breaches = breaches.slice();
        results.crystalHit = crystalHit;
        results.secondLeg = secondLeg;
      }

      // common: update CET1 health color hint via a stored status code
      if (ds.cet1 < ds.cet1Floor) ds.cet1Status = 'breach';
      else if (ds.cet1 < ds.boardTrigger) ds.cet1Status = 'warn';
      else ds.cet1Status = 'ok';

      // push history
      ds.cet1History.push(Math.round(ds.cet1 * 100) / 100);
      ds.portfolioHistory.push(ds.portfolio);
      ds.returnHistory.push(ds.expReturn);
      ds.drawdownHistory.push(ds.drawdown);
      ds.equityHistory.push(ds.wEquity);
      ds.shortHistory.push(ds.wShort);
      ds.longHistory.push(ds.wLong);
      ds.cashHistory.push(ds.wCash);

      results.score = ds.score;

      setTimeout(function () {
        self._updateBriefing({ currentPeriod: (window.mySimulation.state.currentPeriod || round) + 1 });
        self._applyCet1Color();
      }, 500);

      return results;
    }

