      // Event box: shock messaging.
      if (eventBox && eventText) {
        if (round === 1) {
          eventBox.style.display = 'block';
          if (eventTitle) eventTitle.textContent = t('event_r1_title');
          eventText.innerHTML = t('event_r1');
        } else if (round === 4) {
