      var insights = summary.insights || [];
      var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
      var metric = function (label, val) {
        return '<div class="ycc-completion-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
      };
      var metrics = ''
        + metric(t('comp_score_label'), score)
        + metric(t('comp_cet1_label'), (summary.finalCet1 != null ? summary.finalCet1 : '-') + '%')
        + metric(t('comp_return_label'), (summary.finalReturn != null ? summary.finalReturn : '-') + '%')
        + metric(t('comp_breaches_label'), (summary.mandateBreaches != null ? summary.mandateBreaches : 0));
      return ''
        + '<div class="ycc-completion">'
        +   '<div class="ycc-completion-heading">' + t('comp_heading') + '</div>'
        +   '<div class="ycc-completion-verdict">' + grade + '</div>'
