    getPerformanceSummary(history) {
      if (!history.length) return {};
      var sim = window.mySimulation;
      var ds = sim && sim.state ? sim.state.domainState : null;
      var finalCet1 = ds ? ds.cet1 : 0;
      var finalSharpe = ds ? ds.sharpe : 0;
      var finalReturn = ds ? ds.expReturn : 0;
      var totalScore = ds ? ds.score : 0;
      var breaches = ds ? ds.breaches : 0;

      // Distinction requires the whole job: capital held, mandate kept, AND the
      // decade-high yields actually captured (not parked in cash above the rate).
      var grade = 'novice';
      if (totalScore >= 195 && finalCet1 >= 12.0 && breaches === 0 && finalReturn >= 3.9) grade = 'distinction';
      else if (totalScore >= 150 && finalCet1 >= 11.0 && breaches <= 1) grade = 'strong';
      else if (totalScore >= 90 && finalCet1 >= 11.0) grade = 'developing';

      var t = function (k) { return sim ? sim.t(k) : k; };
      var insights = [];
      if (finalCet1 < 11.0) insights.push(t('sum_breach'));
      else if (finalCet1 >= 12.0) insights.push(t('sum_capital_held'));
      if (breaches === 0 && ds && ds.mandateSet) insights.push(t('sum_discipline'));
      else if (breaches > 1) insights.push(t('sum_mandate_broken'));
      if (finalSharpe > 0.6) insights.push(t('sum_sharpe_good'));
      else if (finalSharpe < 0.3) insights.push(t('sum_sharpe_low'));
      if (finalReturn >= 4.0) insights.push(t('sum_yield_captured'));
      else if (finalReturn < 3.4) insights.push(t('sum_over_conservative'));

      return {
        grade: t('grade_' + grade),
        finalCet1: pct1(finalCet1),
        finalReturn: pct1(finalReturn),
        finalSharpe: (Math.round(finalSharpe * 100) / 100).toFixed(2),
        totalScore: Math.round(totalScore),
        mandateBreaches: breaches,
        insights: insights
      };
    }

